// Interfaz que define el contrato para elementos que permiten consultar su estado y cotizar servicios (ISP)
public interface Consultable {
    // Retorna el estado de la conexión de la integración
    String consultarEstado();
    // Cotiza un servicio basado en una descripción en texto
    double cotizar(String detalleServicio);
    // Cotiza un servicio basado directamente en un monto numérico
    double cotizarMonto(double monto);
}